245→mod tests {
246→    use super::*;
247→
248→    #[test]
249→    fn test_adapter_block_chunk_default() {
250→        // Verify default constant is sane
251→        assert_eq!(DEFAULT_BLOCK_CHUNK, 2000);
252→    }
253→
254→    #[test]
255→    fn test_timestamp_overflow_saturates() {
256→        let huge: u64 = u64::MAX;
257→        let result = i64::try_from(huge).unwrap_or(i64::MAX);
258→        assert_eq!(result, i64::MAX);
259→
260→        let normal: u64 = 1_700_000_000;
261→        let result = i64::try_from(normal).unwrap_or(i64::MAX);
262→        assert_eq!(result, 1_700_000_000i64);
263→    }
264→}
