 17→use tracing::{error, info, warn};
 18→use uuid::Uuid;
 19→
 20→#[derive(Parser)]
 21→#[command(about = "Spectraplex CLI", long_about = None)]
 22→struct Cli {
 23→    #[arg(global = true, long, env = "DATABASE_URL")]
 24→    db_url: Option<String>,
 25→
 26→    #[command(subcommand)]
 27→    command: Commands,
 28→}
 29→
 30→#[derive(Subcommand)]
 31→enum Commands {
 32→    /// Initialize the database schema
 33→    InitDb,
 34→
 35→    /// Ingest raw data from blockchain to Bronze layer (JSONL)
 36→    Ingest {
 37→        #[arg(short, long)]
 38→        chain: String,
 39→
 40→        /// Wallet address(es) to ingest. Pass multiple times for batch ingestion.
 41→        #[arg(short, long, required = true, num_args = 1..)]
 42→        wallet: Vec<String>,
 43→
 44→        #[arg(short, long, default_value = "bronze_transactions.jsonl")]
 45→        output: PathBuf,
 46→
 47→        #[arg(long)]
 48→        rpc: Option<String>,
 49→
 50→        #[arg(long)]
 51→        grpc_url: Option<String>,
 52→
 53→        #[arg(long)]
 54→        x_token: Option<String>,
 55→
 56→        #[arg(long, default_value_t = 10)]
 57→        limit: usize,
 58→
 59→        /// User ID to associate with ingested transactions. Auto-generates if not provided.
 60→        #[arg(long)]
 61→        user_id: Option<Uuid>,
 62→    },
 63→    /// Normalize Bronze data to Silver layer (Ledger Entries)
 64→    Normalize {
 65→        #[arg(short, long, default_value = "bronze_transactions.jsonl")]
 66→        input: PathBuf,
 67→
 68→        #[arg(short, long, default_value = "silver_ledger.jsonl")]
 69→        output: PathBuf,
 70→    },
 71→}
 72→
 73→#[tokio::main]
 74→async fn main() -> anyhow::Result<()> {
 75→    dotenvy::dotenv().ok();
 76→
 77→    tracing_subscriber::fmt()
 78→        .with_env_filter(
 79→            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
 80→        )
 81→        .init();
 82→
 83→    let cli = Cli::parse();
 84→
 85→    // Setup DB Pool if URL provided
 86→    let pool = if let Some(url) = &cli.db_url {
 87→        Some(PgPoolOptions::new().max_connections(5).connect(url).await?)
 88→    } else {
 89→        None
 90→    };
 91→
 92→    match cli.command {
 93→        Commands::InitDb => {
 94→            if let Some(p) = pool {
 95→                info!("Running migrations...");
 96→                sqlx::migrate!("../migrations").run(&p).await?;
 97→                info!("Database initialized successfully.");
 98→            } else {
 99→                error!("--db-url is required for InitDb");
100→            }
101→        }
102→        Commands::Ingest {
103→            chain,
104→            wallet: wallets,
105→            output,
106→            rpc,
107→            grpc_url,
108→            x_token,
109→            limit,
110→            user_id,
111→        } => {
112→            let user_id = user_id.unwrap_or_else(|| {
113→                let id = Uuid::new_v4();
114→                info!(user_id = %id, "No --user-id provided, auto-generated");
115→                id
116→            });
117→
118→            for wallet in &wallets {
119→                info!(wallet = %wallet, chain = %chain, "Starting ingestion");
120→
121→                let checkpoint = if let Some(ref p) = pool {
122→                    let repo = Repository::new(p.clone());
123→                    match repo.get_checkpoint(&chain, wallet).await? {
124→                        Some(cp) => {
125→                            info!(
126→                                chain = %chain,
127→                                wallet = %wallet,
128→                                last_signature = ?cp.last_signature,
129→                                last_slot = ?cp.last_slot,
130→                                last_block = ?cp.last_block,
131→                                last_timestamp = ?cp.last_timestamp,
132→                                "Resuming from checkpoint"
133→                            );
134→                            Some(cp)
135→                        }
136→                        None => {
137→                            info!(chain = %chain, wallet = %wallet, "No existing checkpoint, full ingestion");
138→                            None
139→                        }
140→                    }
141→                } else {
142→                    None
143→                };
144→
145→                let events = match chain.as_str() {
146→                    "solana" => {
147→                        if let Some(ref endpoint) = grpc_url {
148→                            let adapter = SolanaGrpcAdapter::new(endpoint, x_token.clone());
149→                            if let Some(ref cp) = checkpoint {
150→                                if let Some(slot) = cp.last_slot {
151→                                    adapter.checkpoint().update(slot as u64);
152→                                }
153→                            }
154→                            adapter
155→                                .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
156→                                .await?
157→                        } else if let Some(ref rpc_url) = rpc {
158→                            let adapter = SolanaAdapter::new(rpc_url);
159→                            adapter
160→                                .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
161→                                .await?
162→                        } else {
163→                            anyhow::bail!("Either --grpc-url or --rpc must be provided for Solana");
164→                        }
165→                    }
166→                    "hyperliquid" => {
167→                        let adapter = HyperliquidAdapter::new();
168→                        adapter
169→                            .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
170→                            .await?
171→                    }
172→                    "ethereum" => {
173→                        let rpc_url = rpc
174→                            .as_ref()
175→                            .ok_or_else(|| anyhow::anyhow!("--rpc is required for Ethereum"))?;
176→                        let adapter = EvmAdapter::new(rpc_url)?;
177→                        adapter
178→                            .fetch_history(wallet, limit, user_id, checkpoint.as_ref())
179→                            .await?
180→                    }
181→                    _ => {
182→                        warn!(chain = %chain, "Unsupported chain");
183→                        return Ok(());
184→                    }
185→                };
186→
187→                if let Some(ref p) = pool {
188→                    let repo = Repository::new(p.clone());
189→
190→                    // Parse chain enum for ensure_wallet_target
191→                    let chain_enum = match chain.as_str() {
192→                        "solana" => Chain::Solana,
193→                        "ethereum" => Chain::Ethereum,
194→                        "hyperliquid" => Chain::Hyperliquid,
195→                        _ => unreachable!("unsupported chain filtered earlier"),
196→                    };
197→
198→                    // Ensure a V2 IndexTarget exists for this wallet (best-effort)
199→                    let target_id = match repo
200→                        .ensure_wallet_target(&chain_enum, wallet, Some(user_id))
201→                        .await
202→                    {
203→                        Ok(target) => Some(target.id),
204→                        Err(e) => {
205→                            warn!(
206→                                error = %e,
207→                                wallet = %wallet,
208→                                "Failed to ensure V2 wallet target (V1 path unaffected)"
209→                            );
210→                            None
211→                        }
212→                    };
213→
214→                    if let Some(cp) = build_checkpoint(&chain, wallet, &events) {
215→                        if let Some(tid) = target_id {
216→                            repo.save_transactions_and_checkpoint_dual_write(&events, &cp, tid)
217→                                .await?;
218→                        } else {
219→                            repo.save_transactions_and_checkpoint(&events, &cp).await?;
220→                        }
221→                        info!(count = events.len(), wallet = %wallet, "Saved transactions to database");
222→                        info!(
223→                            chain = %chain,
224→                            wallet = %wallet,
225→                            last_signature = ?cp.last_signature,
226→                            last_slot = ?cp.last_slot,
227→                            last_block = ?cp.last_block,
228→                            last_timestamp = ?cp.last_timestamp,
229→                            "Checkpoint saved atomically"
230→                        );
231→                    } else {
232→                        if let Some(tid) = target_id {
233→                            repo.save_transactions_dual_write(&events, tid).await?;
234→                        } else {
235→                            repo.save_transactions(&events).await?;
236→                        }
237→                        info!(
238→                            count = events.len(),
239→                            wallet = %wallet,
240→                            "Saved transactions to database (no checkpoint)"
241→                        );
242→                    }
243→                } else {
244→                    let mut file = File::create(&output)?;
245→                    for event in events {
246→                        serde_json::to_writer(&file, &event)?;
247→                        writeln!(file)?;
248→                    }
249→                    info!(path = ?output, wallet = %wallet, "Data written to file");
250→                }
251→            }
252→        }
253→        Commands::Normalize { input, output } => {
254→            let input_str = input.to_string_lossy();
255→            let transactions = if input_str.starts_with("db:") {
256→                let wallet = input_str.strip_prefix("db:").unwrap();
257→                let p = pool
258→                    .clone()
259→                    .ok_or_else(|| anyhow::anyhow!("--db-url is required for db: input"))?;
260→                info!(wallet = %wallet, "Fetching transactions from DB");
261→                let repo = Repository::new(p);
262→                repo.get_transactions_by_wallet(wallet).await?
263→            } else {
264→                info!(path = ?input, "Reading raw data from file");
265→                let file = File::open(&input)?;
266→                let reader = BufReader::new(file);
267→                reader
268→                    .lines()
269→                    .map(|line| {
270→                        let line = line?;
271→                        Ok(serde_json::from_str(&line)?)
272→                    })
273→                    .collect::<anyhow::Result<Vec<Transaction>>>()?
274→            };
275→
276→            let mut all_entries = Vec::new();
277→
278→            for tx in transactions {
279→                let result = match tx.chain {
280→                    spectraplex_core::models::Chain::Solana => {
281→                        solana_parser::parse_solana_transaction(&tx)
282→                    }
283→                    spectraplex_core::models::Chain::Hyperliquid => {
284→                        hyperliquid_parser::parse_hyperliquid_transaction(&tx)
285→                    }
286→                    spectraplex_core::models::Chain::Ethereum => {
287→                        evm_parser::parse_evm_transaction(&tx)
288→                    }
289→                };
290→                match result {
291→                    Ok(entries) => all_entries.extend(entries),
292→                    Err(e) => {
293→                        warn!(tx_hash = %tx.tx_hash, error = %e, "Skipping unparseable transaction");
294→                    }
295→                }
296→            }
297→
298→            if let Some(p) = pool {
299→                info!(
300→                    count = all_entries.len(),
301→                    "Saving ledger entries to database"
302→                );
303→                let repo = Repository::new(p);
304→                repo.save_ledger_entries(&all_entries).await?;
305→                info!("Normalization complete");
306→            } else {
307→                let mut out_file = File::create(&output)?;
308→                for entry in all_entries {
309→                    serde_json::to_writer(&out_file, &entry)?;
310→                    writeln!(out_file)?;
311→                }
312→                info!(path = ?output, "Normalization complete, output written to file");
313→            }
314→        }
315→    }
316→
317→    Ok(())
318→}
