        let json = serde_json::to_value(&spec).unwrap();
        let back: ProtocolFilterSpec = serde_json::from_value(json).unwrap();
        assert_eq!(back.name, "aave_v3");
        assert_eq!(back.addresses["ethereum-mainnet"][0].role, "pool");
    }

